WITH ins AS (INSERT INTO sais_resources (resource_id, family_key, document_number, resource_category, subcategory, jurisdiction_level, jurisdiction, organization_name, organization_type, service_type, official_url, official_contact, statutory_authority, verification_status, last_verified_at, notes, revision) VALUES 
('SAIS-PS-003-05', 'systemic_abuse_intelligence', 403, 'stalking_harassment', 'stalking_civil_protection_order', 'state', 'state -- ALL_STATES', 'Civil Protection Orders for Stalking -- Available Without Any Prior Relationship', 'state_court', 'stalking_civil_protection_order', 'https://www.womenslaw.org/', 'Your local court clerk | Court victim advocate | National DV Hotline: 800-799-7233 | Dial 211 for legal aid', 'State stalking, civil harassment, and sexual assault protection order statutes | Full faith and credit (18 U.S.C. sec. 2265) | Prohibition on protection order fees (34 U.S.C. sec. 12291(b)(2)) | 18 U.S.C. sec. 922(g)(8) where the order qualifies.', 'VERIFIED', '2026-08-17', 'YOU DO NOT NEED A RELATIONSHIP WITH THE PERSON TO GET A PROTECTION ORDER. Nearly every state has a stalking or civil harassment order available against a stranger, neighbor, or coworker -- ask the clerk which form fits. Then calendar the FULL HEARING, because the temporary order dissolves if you do not appear, and ask explicitly for a bar on SURVEILLANCE AND TRACKING, which standard forms frequently omit. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-003 | pipeline: Stalking and Harassment] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 308dc6385c4685bb05465dd77236d43f9c5a9bcd0f539e702833250cbe1ce8a7]', 'v1.0'),
('SAIS-PS-003-06', 'systemic_abuse_intelligence', 403, 'stalking_harassment', 'stalking_institutional_protections', 'federal + state', 'federal + state -- ALL_STATES', 'Institutional Protections -- Workplace, School, Landlord, and Victim Compensation', 'state_agency | federal_agency', 'stalking_institutional_protections', 'https://ovc.ojp.gov/', 'Your state crime victim compensation program -- see jurisdiction table | HUD: 800-669-9777 | Your school''s Title IX office | Dial 211', 'Title IX (20 U.S.C. sec. 1681; 34 CFR Part 106) | Clery Act and VAWA campus provisions (20 U.S.C. sec. 1092(f)) | VAWA housing protections (34 U.S.C. sec. 12491) | Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | State survivor employment leave and lease termination statutes.', 'VERIFIED', '2026-08-17', 'ASK YOUR SCHOOL FOR TITLE IX SUPPORTIVE MEASURES AND YOUR STATE FOR CRIME VICTIM COMPENSATION -- both cover stalking, both are available without a police report or a formal complaint, and both are systematically underused. At work, ask whether your employer can seek a WORKPLACE VIOLENCE RESTRAINING ORDER in its own name; in many states they can, and it keeps you out of the middle of the confrontation. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-003 | pipeline: Stalking and Harassment] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 61f37c0917381823f0945a7c26198122085a45293e5430b185a36102c93fa1aa]', 'v1.0'),
('SAIS-PS-004-01', 'systemic_abuse_intelligence', 404, 'emergency_protective_order', 'epo_emergency_ex_parte_route', 'state', 'state -- ALL_STATES', 'Emergency and Ex Parte Orders -- Same-Day Protection in Every State', 'state_court | law_enforcement', 'epo_emergency_ex_parte_route', 'https://www.womenslaw.org/', '911 for immediate danger | National Domestic Violence Hotline: 800-799-7233 | TTY 800-787-3224 | Text START to 88788 | Your local court clerk', 'Violence Against Women Act (34 U.S.C. sec. 12291 et seq.) | Prohibition on fees for protection orders (34 U.S.C. sec. 12291(b)(2)) | Full faith and credit for protection orders (18 U.S.C. sec. 2265) | State domestic violence and civil protection order statutes.', 'VERIFIED', '2026-08-17', 'GO TODAY, AND IF THE COURTHOUSE IS CLOSED ASK LAW ENFORCEMENT FOR AN EMERGENCY PROTECTIVE ORDER BY NAME. No lawyer, no fee, no police report, and no visible injuries are required. Then calendar the FULL HEARING DATE immediately -- a temporary order dissolves if you do not appear, and that single missed date is how most people lose protection they had already obtained. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-004 | pipeline: Emergency Protective Order] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: e2569ff47447b81cb7d3bcc3d695c7ecf5acc10feb38be6b1f2ca0321f1809f9]', 'v1.0'),
('SAIS-PS-004-02', 'systemic_abuse_intelligence', 404, 'emergency_protective_order', 'epo_petition_drafting', 'state', 'state -- ALL_STATES', 'Drafting the Petition -- Specificity Is What Judges Grant On', 'state_court | victim_advocate', 'epo_petition_drafting', 'https://www.womenslaw.org/', 'Court self-help center or clerk | Local DV advocate via 800-799-7233 | Your state DV coalition -- see jurisdiction table', 'State civil protection order statutes | Violence Against Women Act (34 U.S.C. sec. 12291) | Pet protection provisions in state DV statutes | State exclusive-use-of-residence provisions.', 'VERIFIED', '2026-08-17', 'LEAD WITH THE MOST RECENT INCIDENT IN CONCRETE DETAIL -- date, time, place, words, actions, injuries, witnesses -- then the pattern. And ASK FOR EVERY FORM OF RELIEF EXPLICITLY, including exclusive use of the residence, firearm surrender, pet custody, and stay-away from the workplace. Courts grant what is requested; relief you do not name is relief you generally do not get. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-004 | pipeline: Emergency Protective Order] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: d60c1e105e92db99819fbe164e5fa4a9d08de518a09f72303d470b30bf06e0fe]', 'v1.0'),
('SAIS-PS-004-03', 'systemic_abuse_intelligence', 404, 'emergency_protective_order', 'epo_firearm_prohibition_surrender', 'federal + state', 'federal + state -- ALL_STATES', 'Firearm Prohibition and Surrender Under a Protective Order', 'federal_agency | state_court | law_enforcement', 'epo_firearm_prohibition_surrender', 'https://www.atf.gov/rules-and-regulations/domestic-violence', '911 for immediate danger | Your local court clerk and law enforcement agency | National DV Hotline: 800-799-7233', '18 U.S.C. sec. 922(g)(8) (possession while subject to a qualifying protection order) | 18 U.S.C. sec. 922(g)(9) (misdemeanor crime of domestic violence) | 18 U.S.C. sec. 922(d)(8)-(9) (transfer prohibitions) | Violence Against Women Act (34 U.S.C. sec. 12291) | State firearm relinquishment statutes.', 'VERIFIED', '2026-08-17', 'ASK THE JUDGE ON THE RECORD FOR A CREDIBLE-THREAT FINDING AND FOR LANGUAGE EXPRESSLY PROHIBITING THE USE OR THREATENED USE OF PHYSICAL FORCE. Those specific words are what trigger the federal firearm prohibition under 18 U.S.C. sec. 922(g)(8), an ex parte order frequently does not qualify without them, and no one will add them unless asked. Then ask separately for SURRENDER and a COMPLIANCE HEARING -- prohibition and collection are two different things. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: PS-004 | pipeline: Emergency Protective Order] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 226559ce58f7e84f6b2dd0760e908f9458d2546c947a8c2deb1e78979cc819bd]', 'v1.0'),
('SAIS-PS-004-04', 'systemic_abuse_intelligence', 404, 'emergency_protective_order', 'epo_service_and_enforcement', 'federal + state', 'federal + state -- ALL_STATES', 'Making the Order Work -- Service, Carrying It, and Interstate Enforcement', 'law_enforcement | state_court', 'epo_service_and_enforcement', 'https://www.womenslaw.org/', '911 to report any violation | Your local law enforcement records division | Court clerk for certified copies', 'Full faith and credit for protection orders (18 U.S.C. sec. 2265) | Interstate violation of a protection order (18 U.S.C. sec. 2262) | Interstate stalking and domestic violence (18 U.S.C. sec. 2261, 2261A) | Violence Against Women Act (34 U.S.C. sec. 12291) | State registry and enforcement statutes.', 'VERIFIED', '2026-08-17', 'YOUR ORDER IS ENFORCEABLE IN EVERY STATE, TERRITORY, AND TRIBAL JURISDICTION WITHOUT REGISTRATION UNDER 18 U.S.C. sec. 2265. If an officer says otherwise, say the statute number and ask for a supervisor. And confirm SERVICE actually happened -- an unserved order is generally unenforceable, service is free through law enforcement in DV cases, and the return of service should be in the court file. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-004 | pipeline: Emergency Protective Order] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: fd0960f5a36e6d84fd72042edd4ee642da2b6f96770c47ba632234ada4ae53d4]', 'v1.0'),
('SAIS-PS-004-05', 'systemic_abuse_intelligence', 404, 'emergency_protective_order', 'epo_full_hearing', 'state', 'state -- ALL_STATES', 'Preparing For and Appearing at the Full Hearing', 'state_court | victim_advocate', 'epo_full_hearing', 'https://www.womenslaw.org/', 'Court victim advocate | Your state DV coalition -- see jurisdiction table | National DV Hotline: 800-799-7233 | Dial 211 for legal aid', 'State civil protection order statutes and hearing procedures | Violence Against Women Act (34 U.S.C. sec. 12291) | 18 U.S.C. sec. 922(g)(8) (hearing and findings requirements) | State victim advocate and courtroom accommodation provisions.', 'VERIFIED', '2026-08-17', 'APPEAR AT THE FULL HEARING NO MATTER WHAT. Non-appearance dissolves the temporary order and is the single largest cause of lost protection. Ask for safety accommodations in advance, ask for FINDINGS rather than a bare consent order, and before you leave the courtroom write down the expiration date and the renewal procedure. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-004 | pipeline: Emergency Protective Order] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 4b5dc48ee74c5d5cf8afd22500d4138d0d67d9f37eaac709c8db5b79a99232ae]', 'v1.0'),
('SAIS-PS-004-06', 'systemic_abuse_intelligence', 404, 'emergency_protective_order', 'epo_limits_and_layered_protections', 'federal + state', 'federal + state -- ALL_STATES', 'The Limits of a Protective Order and the Protections to Add', 'state_agency | federal_program', 'epo_limits_and_layered_protections', 'https://www.womenslaw.org/', 'National DV Hotline: 800-799-7233 | Your state Address Confidentiality Program | State crime victim compensation program | Dial 211', 'Violence Against Women Act (34 U.S.C. sec. 12291) | Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | VAWA immigration protections (8 U.S.C. sec. 1154(a)(1)(A)(iii); U visa 8 U.S.C. sec. 1101(a)(15)(U); T visa sec. 1101(a)(15)(T)) | State address confidentiality and survivor employment leave statutes.', 'VERIFIED', '2026-08-17', 'ENROLL IN YOUR STATE''S ADDRESS CONFIDENTIALITY PROGRAM BEFORE YOU MOVE. It substitutes a legal address across public records and forwards mail, and it is far more effective as prevention than as cleanup. Then treat the order as one layer among several -- safety plan, digital security, school and workplace notification, victim compensation, and immigration protections all operate independently of it. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-004 | pipeline: Emergency Protective Order] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: df5926fbb0880298b969b1956de26c12957861ae9369801da2a45b8fb9711ebd]', 'v1.0'),
('SAIS-PS-005-01', 'systemic_abuse_intelligence', 405, 'victim_compensation', 'victim_compensation_eligibility', 'federal + state', 'federal + state -- ALL_STATES', 'Crime Victim Compensation -- The Program Most Eligible People Never Apply To', 'state_agency | federal_program', 'victim_compensation_eligibility', 'https://ovc.ojp.gov/directory-crime-victim-services', 'VictimConnect: 855-484-2846 | Your state compensation program -- see jurisdiction table | OVC directory: ovc.ojp.gov', 'Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | VOCA compensation program requirements (28 CFR Part 94) | Crime Victims'' Rights Act (18 U.S.C. sec. 3771) | State crime victim compensation statutes.', 'VERIFIED', '2026-08-17', 'APPLY EVEN IF YOU ARE UNSURE YOU QUALIFY, AND EVEN IF NOBODY WAS EVER ARRESTED. No arrest, charge, or conviction is required -- only a report and reasonable cooperation. Immigration status is not a bar in most states. Surviving family members, dependents, witnesses, and children who witnessed violence are frequently eligible in their own right and almost never apply. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-005 | pipeline: Victim Compensation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: f9c891e061651df4174256bb347e8e04682fd0bf80ceda929e1f0ab9e3a01f58]', 'v1.0'),
('SAIS-PS-005-02', 'systemic_abuse_intelligence', 405, 'victim_compensation', 'victim_compensation_covered_costs', 'state', 'state -- ALL_STATES', 'Covered Costs -- Medical, Counseling, Relocation, Security, and Lost Income', 'state_agency', 'victim_compensation_covered_costs', 'https://ovc.ojp.gov/directory-crime-victim-services', 'Your state compensation program -- see jurisdiction table | VictimConnect: 855-484-2846 | Local VOCA victim assistance provider', 'Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | VOCA compensation requirements (28 CFR Part 94) | State compensation statutes defining covered expense categories | State restitution and subrogation provisions.', 'VERIFIED', '2026-08-17', 'CLAIM RELOCATION, SECURITY MEASURES, TRANSPORTATION, AND CHILDCARE -- these exist in many states and are almost never claimed because the intake form does not advertise them. And an insurance denial does not disqualify you: compensation is the payer of LAST RESORT, so the denial is exactly the documentation the program needs to pay. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-005 | pipeline: Victim Compensation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 457afd804b018c828468ea039770c2cc2203e6c2d7ed75e730d028c536f67f5f]', 'v1.0'),
('SAIS-PS-005-03', 'systemic_abuse_intelligence', 405, 'victim_compensation', 'victim_compensation_deadlines', 'state', 'state -- ALL_STATES', 'Reporting and Filing Deadlines -- and the Good-Cause Exceptions', 'state_agency | law_enforcement', 'victim_compensation_deadlines', 'https://ovc.ojp.gov/directory-crime-victim-services', 'Your state compensation program -- see jurisdiction table | Local law enforcement | VictimConnect: 855-484-2846', 'Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | VOCA compensation requirements (28 CFR Part 94) | State compensation reporting and filing deadline statutes and good-cause provisions.', 'VERIFIED', '2026-08-17', 'APPLY EVEN IF YOU THINK YOU MISSED THE DEADLINE, AND ASK FOR A GOOD-CAUSE WAIVER IN WRITING. Every state has one, they are granted more often than people expect, and for crimes against MINORS the clock frequently runs from the eighteenth birthday rather than the incident. A late denial is appealable; a claim never filed is not. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-005 | pipeline: Victim Compensation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: f83d523ff101e09fe4334684b72ae7fdaeaa1c7f82a4e165e965d42049ed216e]', 'v1.0'),
('SAIS-PS-005-04', 'systemic_abuse_intelligence', 405, 'victim_compensation', 'victim_compensation_filing', 'state', 'state -- ALL_STATES', 'Filing the Claim -- Documentation and the Free Help That Improves the Outcome', 'state_agency | nonprofit_organization', 'victim_compensation_filing', 'https://ovc.ojp.gov/directory-crime-victim-services', 'Local VOCA-funded victim assistance provider | Prosecutor''s victim-witness unit | VictimConnect: 855-484-2846 | Your state program -- see jurisdiction table', 'Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | VOCA compensation requirements (28 CFR Part 94) | Crime Victims'' Rights Act (18 U.S.C. sec. 3771) | State compensation statutes on contributory conduct and cooperation requirements.', 'VERIFIED', '2026-08-17', 'HAVE A VOCA-FUNDED ADVOCATE OR THE PROSECUTOR''S VICTIM-WITNESS UNIT PREPARE THE APPLICATION WITH YOU -- it is free and it materially improves approval rates. And if you are denied for CONTRIBUTORY CONDUCT, appeal it. That finding is applied inconsistently and is frequently reversed where the applicant was defending themselves or was a survivor of ongoing abuse. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-005 | pipeline: Victim Compensation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: d2d1eb44a0d4f69703ef348eb8e11d8061ef25f3277a1eeae45811e06cec0919]', 'v1.0'),
('SAIS-PS-005-05', 'systemic_abuse_intelligence', 405, 'victim_compensation', 'victim_compensation_restitution', 'federal + state', 'federal + state -- ALL_STATES', 'Restitution -- A Distinct Right, Available Only If You Are in the Case', 'state_court | federal_agency', 'victim_compensation_restitution', 'https://ovc.ojp.gov/', 'The prosecutor''s victim-witness unit | Your state compensation program | VictimConnect: 855-484-2846', 'Mandatory Victims Restitution Act (18 U.S.C. sec. 3663A) | General federal restitution (18 U.S.C. sec. 3663) | Crime Victims'' Rights Act (18 U.S.C. sec. 3771) | Bankruptcy nondischargeability (11 U.S.C. sec. 523(a)(13)) | State restitution statutes.', 'VERIFIED', '2026-08-17', 'KEEP YOUR CONTACT INFORMATION CURRENT WITH THE PROSECUTOR AND THE COURT, AND SUBMIT A DOCUMENTED LOSS STATEMENT BEFORE SENTENCING. Restitution cannot be paid to someone the system cannot locate, unclaimed restitution is common, and courts order only what is proven at sentencing. Pursue restitution AND compensation -- they come from different sources and are not alternatives. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-005 | pipeline: Victim Compensation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 7f6866975c2bfd142ce2f3e71c346318556360f6f7d1ee96fd6d86a3af34d0cd]', 'v1.0'),
('SAIS-PS-005-06', 'systemic_abuse_intelligence', 405, 'victim_compensation', 'victim_compensation_other_recovery_routes', 'federal + state', 'federal + state -- ALL_STATES', 'Beyond Compensation -- Civil Suits, Benefits, and Other Recovery Routes', 'state_court | federal_program', 'victim_compensation_other_recovery_routes', 'https://www.lawhelp.org/', 'Your state bar lawyer referral service | Dial 211 | VictimConnect: 855-484-2846 | Your state unemployment agency', 'Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | U visa and T visa (8 U.S.C. sec. 1101(a)(15)(U), (T)) | VAWA housing protections (34 U.S.C. sec. 12491) | Fair Credit Reporting Act identity theft block (15 U.S.C. sec. 1681c-2) | State crime victim tolling statutes.', 'VERIFIED', '2026-08-17', 'ASK ABOUT A THIRD-PARTY CIVIL CLAIM AND SEND AN EVIDENCE PRESERVATION DEMAND IMMEDIATELY. Offenders are frequently judgment-proof, which makes a negligent property owner, employer, or business the only realistic route to meaningful recovery -- and the surveillance video and incident reports that case depends on are retained for weeks, not years. Many states also extend the limitations period for crime victims. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-005 | pipeline: Victim Compensation] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 78d66e477242f1bfe3dcff94cd601e7169c9d65fb67d47146d8a4f05d24199bd]', 'v1.0'),
('SAIS-PS-007-01', 'systemic_abuse_intelligence', 407, 'hate_crime', 'hate_crime_legal_structure', 'federal + state', 'federal + state -- ALL_STATES', 'The Legal Structure -- Bias Motivation Layered on a Base Offense', 'law_enforcement | federal_agency', 'hate_crime_legal_structure', 'https://www.justice.gov/hatecrimes', '911 for immediate danger | FBI tips: tips.fbi.gov or 800-225-5324 | Your local law enforcement | VictimConnect: 855-484-2846', 'Matthew Shepard and James Byrd Jr. Hate Crimes Prevention Act (18 U.S.C. sec. 249) | Federally protected activities (18 U.S.C. sec. 245) | Damage to religious property (18 U.S.C. sec. 247) | Criminal interference with housing rights (42 U.S.C. sec. 3631) | State hate crime and bias enhancement statutes.', 'VERIFIED', '2026-08-17', 'THE BIAS DOES NOT HAVE TO BE THE ONLY MOTIVE, AND THE OFFENDER CAN BE WRONG ABOUT WHO YOU ARE. Most statutes require only that the protected characteristic was a substantial or motivating factor, and ''actual or perceived'' covers mistaken assumptions. Say both of those things if an officer tells you it does not qualify because there was another reason for the confrontation. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-007 | pipeline: Hate Crime] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: cd3df8a7c3ce346f5b6306a97d8bb83032f37218188f725e41a087996b8b24e8]', 'v1.0'),
('SAIS-PS-007-02', 'systemic_abuse_intelligence', 407, 'hate_crime', 'hate_crime_bias_documentation', 'federal + state', 'federal + state -- ALL_STATES', 'Documenting Bias Indicators -- What Actually Proves Motive', 'law_enforcement | victim_advocate', 'hate_crime_bias_documentation', 'https://www.justice.gov/hatecrimes/get-help-now', 'Local law enforcement | FBI tips: tips.fbi.gov | VictimConnect: 855-484-2846 | Local civil rights organization', 'Hate Crimes Prevention Act (18 U.S.C. sec. 249) | Hate Crime Statistics Act (34 U.S.C. sec. 41305) | Khalid Jabara and Heather Heyer NO HATE Act | Preservation of stored records (18 U.S.C. sec. 2703(f)) | State bias crime reporting statutes.', 'VERIFIED', '2026-08-17', 'QUOTE THE EXACT WORDS, EVEN THE ONES THAT ARE HARD TO WRITE, AND PHOTOGRAPH EVERYTHING BEFORE CLEANUP. Slurs and statements are the most direct proof of motive, and graffiti and damage are routinely erased within hours by people trying to help. Then ask police IN WRITING to note the bias indicators in the report -- an incident recorded without a bias flag never enters hate crime tracking or specialized review. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-007 | pipeline: Hate Crime] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: a44d370ecf7628a00aee20f51d4fb3fb9b531173cc53deb4b47dad67a5769e7d]', 'v1.0'),
('SAIS-PS-007-03', 'systemic_abuse_intelligence', 407, 'hate_crime', 'hate_crime_reporting_routes', 'federal + state', 'federal + state -- ALL_STATES', 'Where to Report -- Four Authorities With Independent Jurisdiction', 'law_enforcement | federal_agency | state_agency', 'hate_crime_reporting_routes', 'https://www.justice.gov/hatecrimes/report-hate-crime', '911 for immediate danger | FBI: tips.fbi.gov or 800-225-5324 | DOJ Community Relations Service | Your state AG civil rights unit -- see jurisdiction table', 'Hate Crimes Prevention Act (18 U.S.C. sec. 249) | Federally protected activities (18 U.S.C. sec. 245) | Damage to religious property (18 U.S.C. sec. 247) | Criminal interference with housing rights (42 U.S.C. sec. 3631) | Community Relations Service (42 U.S.C. sec. 2000g) | State civil rights commission statutes.', 'VERIFIED', '2026-08-17', 'FILE WITH ALL FOUR -- LOCAL POLICE, THE FBI, THE STATE ATTORNEY GENERAL, AND THE STATE CIVIL RIGHTS COMMISSION. Their authority is independent, so a local declination does not end it. And watch the CIVIL clock: human rights commission and fair housing deadlines run 180 days to 1 year and expire while people are still waiting on the criminal case. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: PS-007 | pipeline: Hate Crime] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 7598d4f70fd2ac567e52e433d6a022c932dc66d804b5f3b45e64fed5e3142fff]', 'v1.0'),
('SAIS-PS-007-04', 'systemic_abuse_intelligence', 407, 'hate_crime', 'hate_crime_civil_remedies', 'federal + state', 'federal + state -- ALL_STATES', 'Civil Rights Claims -- Suing Independently of Any Criminal Outcome', 'state_court | federal_agency', 'hate_crime_civil_remedies', 'https://www.lawhelp.org/', 'Your state bar lawyer referral service | Local civil rights legal organization | LSC legal aid: lsc.gov/find-legal-aid | Dial 211', '42 U.S.C. sec. 1983 (deprivation of rights under color of law) | 42 U.S.C. sec. 1985 (conspiracy to interfere with civil rights) | 42 U.S.C. sec. 1981, 1982 (contract and property rights) | Fair Housing Act (42 U.S.C. sec. 3601 et seq.) | Title VII (42 U.S.C. sec. 2000e) | Title VI (42 U.S.C. sec. 2000d) | State hate crime civil action statutes.', 'VERIFIED', '2026-08-17', 'ASK WHETHER YOUR STATE HAS A HATE CRIME CIVIL ACTION WITH FEE-SHIFTING -- most do, and the fee provision is what makes an attorney able to take the case. Then look past the individual offender to the INSTITUTION: landlords, employers, and schools that knew and failed to act are frequently the only solvent defendant, and their video and complaint files are the evidence -- send a preservation demand today. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: PS-007 | pipeline: Hate Crime] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: ee08e4f4fe20e28f31e35c6f3bb75d58b8f9d67b149c105eeb76532c0b61c433]', 'v1.0'),
('SAIS-PS-007-05', 'systemic_abuse_intelligence', 407, 'hate_crime', 'hate_crime_support_and_compensation', 'federal + state', 'federal + state -- ALL_STATES', 'Support and Compensation -- Individual and Community', 'state_agency | nonprofit_organization', 'hate_crime_support_and_compensation', 'https://ovc.ojp.gov/', 'Your state crime victim compensation program -- see jurisdiction table | VictimConnect: 855-484-2846 | 988 | DOJ Community Relations Service', 'Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | Community Relations Service (42 U.S.C. sec. 2000g) | Khalid Jabara and Heather Heyer NO HATE Act | Nonprofit Security Grant Program (6 U.S.C. sec. 609a) | Title VI language access (42 U.S.C. sec. 2000d)', 'VERIFIED', '2026-08-17', 'APPLY FOR CRIME VICTIM COMPENSATION AND CLAIM RELOCATION, SECURITY MEASURES, AND COUNSELING -- hate crimes qualify in every state and those three categories are among the least claimed. If an institution was targeted, ask about NONPROFIT SECURITY GRANT funding, which is separate money and widely unused. And the DOJ Community Relations Service will facilitate community repair for free without investigating anyone. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-007 | pipeline: Hate Crime] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: abf1b349e8fe92a93811b44d0aab0a9a0fce3bac099821238f0ed19dab5db84d]', 'v1.0'),
('SAIS-PS-007-06', 'systemic_abuse_intelligence', 407, 'hate_crime', 'hate_crime_non_criminal_bias_incidents', 'federal + state', 'federal + state -- ALL_STATES', 'Bias Incidents Below the Criminal Threshold -- The Remedies That Still Exist', 'state_agency | federal_agency', 'hate_crime_non_criminal_bias_incidents', 'https://www.justice.gov/hatecrimes', 'Your state human rights commission -- see jurisdiction table | HUD: 800-669-9777 | EEOC: 800-669-4000 | ED Office for Civil Rights', 'Fair Housing Act (42 U.S.C. sec. 3601 et seq.) | Title VII (42 U.S.C. sec. 2000e) | Title VI (42 U.S.C. sec. 2000d) | Title IX (20 U.S.C. sec. 1681) | ADA Titles II and III (42 U.S.C. sec. 12131, 12181) | 42 U.S.C. sec. 1981, 1982 | State human rights acts.', 'VERIFIED', '2026-08-17', 'A BIAS INCIDENT THAT IS NOT A CRIME IS STILL ACTIONABLE THROUGH THE CIVIL RIGHTS TRACK -- housing, employment, education, and public accommodations all have enforcement routes that reach conduct the criminal law does not. But those clocks are SHORT: 180 days for employment and education, one year for housing, and 90 days to sue after a right-to-sue notice. They expire quietly while people wait to see whether police will act. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: PS-007 | pipeline: Hate Crime] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: d5feca85c1f8041008e75de584068766eab4ea61d954b54a1301d9167b27790e]', 'v1.0'),
('SAIS-PS-009-01', 'systemic_abuse_intelligence', 409, 'campus_safety', 'campus_supportive_measures', 'federal', 'federal -- NATIONWIDE', 'Supportive Measures -- The Help That Does Not Require Filing Anything', 'educational_institution | federal_agency', 'campus_supportive_measures', 'https://www.ed.gov/ocr', 'Your school''s Title IX Coordinator (must be published on the school website) | ED Office for Civil Rights | RAINN: 800-656-4673 | VictimConnect: 855-484-2846', 'Title IX (20 U.S.C. sec. 1681; 34 CFR Part 106) | Title IX supportive measures requirement (34 CFR 106.44) | Clery Act (20 U.S.C. sec. 1092(f)) | Section 504 and ADA (29 U.S.C. sec. 794; 42 U.S.C. sec. 12131) | State campus safety statutes.', 'VERIFIED', '2026-08-17', 'ASK FOR SUPPORTIVE MEASURES IN WRITING TODAY AND USE THAT EXACT PHRASE. They must be offered regardless of whether you file a complaint or report to police, they are not conditioned on participating in any process, and most students never learn they exist. And if the school''s remedy moves YOU out of your classes or housing while the other person stays, say it is unreasonably burdensome and demand the alternative in writing. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: PS-009 | pipeline: Campus Safety] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 678098916cb7e22ea740cfa24a63af93088a57f898e19c6fe0a42fe8b3831bd3]', 'v1.0')
